function openMovement(){const collabs=state.data.colaboradores.filter(c=>c.ativo!==false).sort((a,b)=>byName(a,b,"nomeCompleto"));const works=state.data.obras.filter(o=>!["Encerrada","Cancelada"].includes(o.status)).sort((a,b)=>byName(a,b,"nome"));const epis=state.data.epis.filter(x=>x.ativo!==false).sort((a,b)=>byName(a,b,"nome"));const kits=state.data.kits.filter(x=>x.status==="Disponível").sort((a,b)=>byName(a,b,"codigo"));const eqs=state.data.equipamentos.filter(x=>x.status==="Disponível").sort((a,b)=>byName(a,b,"tag"));modal("Nova movimentação",`<form id="movement-form"><div class="form-grid">${selectField("Colaborador","colaboradorId",[["","Selecione"],...collabs.map(c=>[c.id,c.nomeCompleto])],"",{required:true})}${selectField("Obra","obraId",[["","Sem obra"],...works.map(o=>[o.id,o.nome])])}${selectField("Movimento","movimento",["Entrega","Troca","Cessão temporária"],"Entrega")}${field("Motivo / condição","motivoCondicao","Entrega para uso")}</div><div class="section-separator"></div><div class="three-column"><div><label class="strong small">EPIs / uniformes</label><div class="checkbox-list">${epis.map(x=>`<label class="checkbox-item"><input type="checkbox" name="epiItems" value="${x.id}"><span>${esc(x.nome)} <span class="muted">(saldo ${stockFor(x.id)})</span></span><input class="qty-inline" type="number" name="qty_${x.id}" min="1" value="1" aria-label="Quantidade"></label>`).join("")||`<div class="empty-state">Sem EPIs cadastrados.</div>`}</div></div><div><label class="strong small">KITs</label><div class="checkbox-list">${kits.map(x=>`<label class="checkbox-item"><input type="checkbox" name="kitItems" value="${x.id}"><span><strong>${esc(x.codigo)}</strong> — ${esc(x.categoria||x.descricao||"KIT")}</span></label>`).join("")||`<div class="empty-state">Sem KITs disponíveis.</div>`}</div></div><div><label class="strong small">Equipamentos / cordas</label><div class="checkbox-list">${eqs.map(x=>`<label class="checkbox-item"><input type="checkbox" name="equipmentItems" value="${x.id}"><span><strong>${esc(x.tag)}</strong> — ${esc(x.equipamento)}</span></label>`).join("")||`<div class="empty-state">Sem equipamentos disponíveis.</div>`}</div></div></div><div class="form-help">Todos os itens selecionados formarão uma única movimentação e serão confirmados com uma única assinatura.</div><div id="modal-msg"></div></form>`,{wide:true,footer:`<button class="secondary-button" data-close-modal>Cancelar</button><button class="module-primary-button" type="submit" form="movement-form">Gerar para assinatura</button>`});$("#movement-form").onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),items=[];for(const id of fd.getAll("epiItems"))items.push({tipoItem:"epi",itemId:id,quantidade:Number(fd.get(`qty_${id}`)||1)});for(const id of fd.getAll("kitItems"))items.push({tipoItem:"kit",itemId:id,quantidade:1});for(const id of fd.getAll("equipmentItems"))items.push({tipoItem:"equipamento",itemId:id,quantidade:1});if(!items.length){$("#modal-msg").innerHTML=msgBox("Selecione ao menos um item.");return;}try{await createMovementGroup({colaboradorId:fd.get("colaboradorId"),obraId:fd.get("obraId"),movimento:fd.get("movimento"),motivoCondicao:fd.get("motivoCondicao"),items});closeModal();showToast("Movimentação criada e enviada para uma única assinatura.");}catch(err){console.error(err);$("#modal-msg").innerHTML=msgBox(friendlyWriteError(err));}};}
async function createMovementGroup({colaboradorId,obraId="",movimento="Entrega",motivoCondicao="",items=[]},{mobilizacaoId=""}={}){const c=findBy("colaboradores",colaboradorId),o=findBy("obras",obraId);if(!c)throw new Error("Selecione o colaborador.");if(!items.length)throw new Error("Selecione ao menos um item.");const grupoId=(globalThis.crypto?.randomUUID?.()||`grp-${Date.now()}-${Math.random().toString(36).slice(2)}`);const prepared=[];const reservedEquipment=new Set();const epiTotals=new Map();for(const raw of items){const qty=Math.max(1,Number(raw.quantidade||1));if(raw.tipoItem==="epi"){const e=findBy("epis",raw.itemId);if(!e)throw new Error("EPI inválido.");epiTotals.set(e.id,(epiTotals.get(e.id)||0)+qty);prepared.push({...raw,quantidade:qty,itemDescricao:e.nome,caTagSerie:e.ca||"",componentesSnapshot:[]});}else if(raw.tipoItem==="kit"){const k=findBy("kits",raw.itemId);if(!k||k.status!=="Disponível")throw new Error(`KIT ${k?.codigo||""} indisponível.`);const snap=(k.componentes||[]).map(id=>{const e=findBy("equipamentos",id);return e?{id:e.id,tag:e.tag,equipamento:e.equipamento,serie:e.numeroSerie||"",status:e.status}:null}).filter(Boolean);if(snap.some(x=>x.status!=="Disponível"))throw new Error(`O KIT ${k.codigo} possui componente indisponível.`);for(const x of snap){if(reservedEquipment.has(x.id))throw new Error("Há equipamento repetido entre os KITs selecionados.");reservedEquipment.add(x.id);}prepared.push({...raw,quantidade:1,itemDescricao:k.codigo,caTagSerie:k.codigo,componentesSnapshot:snap});}else{const eq=findBy("equipamentos",raw.itemId);if(!eq||eq.status!=="Disponível")throw new Error(`Equipamento ${eq?.tag||""} indisponível.`);if(reservedEquipment.has(eq.id))throw new Error("O mesmo equipamento foi selecionado mais de uma vez.");reservedEquipment.add(eq.id);prepared.push({...raw,quantidade:1,itemDescricao:`${eq.tag} — ${eq.equipamento}`,caTagSerie:[eq.tag,eq.numeroSerie].filter(Boolean).join(" / "),componentesSnapshot:[]});}}for(const [epiId,total] of epiTotals){const e=findBy("epis",epiId);if(stockFor(epiId)<total)throw new Error(`Estoque insuficiente de ${e?.nome||"EPI"}.`);}const batch=writeBatch(db),refs=[];for(const p of prepared){const ref=doc(collection(db,"movimentacoes"));refs.push(ref);batch.set(ref,{grupoId,grupoQuantidade:prepared.length,colaboradorId:c.id,colaboradorNome:c.nomeCompleto,obraId:o?.id||"",obraNome:o?.nome||"",tipoItem:p.tipoItem,itemId:p.itemId,itemDescricao:p.itemDescricao,caTagSerie:p.caTagSerie,quantidade:p.quantidade,movimento,motivoCondicao,statusAssinatura:"pendente",estado:"aguardando_assinatura",assinaturaTipo:"recebimento",componentesSnapshot:p.componentesSnapshot,mobilizacaoId,criadoEm:serverTimestamp(),criadoPor:state.user.uid});if(p.tipoItem==="epi"){const e=findBy("epis",p.itemId),sr=doc(collection(db,"estoque_movimentacoes"));batch.set(sr,{epiId:e.id,epiNome:e.nome,tipo:"Saída por entrega",quantidade:-p.quantidade,obraId:o?.id||"",obraNome:o?.nome||"",movimentacaoId:ref.id,grupoId,observacao:`${c.nomeCompleto} — ${movimento}`,criadoEm:serverTimestamp(),criadoPor:state.user.uid});}else if(p.tipoItem==="kit"){batch.update(doc(db,"kits",p.itemId),{status:"Reservado",responsavelColaboradorId:c.id,responsavelNome:c.nomeCompleto,atualizadoEm:serverTimestamp(),atualizadoPor:state.user.uid});for(const comp of p.componentesSnapshot)batch.update(doc(db,"equipamentos",comp.id),{status:"Reservado",responsavelColaboradorId:c.id,responsavelNome:c.nomeCompleto,atualizadoEm:serverTimestamp(),atualizadoPor:state.user.uid});}else batch.update(doc(db,"equipamentos",p.itemId),{status:"Reservado",responsavelColaboradorId:c.id,responsavelNome:c.nomeCompleto,atualizadoEm:serverTimestamp(),atualizadoPor:state.user.uid});}await batch.commit();await audit("Movimentação criada","movimentacao",grupoId,`${c.nomeCompleto} — ${prepared.length} item(ns)`);return refs.map(r=>r.id);}
async function createMovement(f,opts={}){return createMovementGroup({colaboradorId:f.colaboradorId,obraId:f.obraId||"",movimento:f.movimento||"Entrega",motivoCondicao:f.motivoCondicao||"",items:[{tipoItem:f.tipoItem,itemId:f.itemId,quantidade:Number(f.quantidade||1)}]},opts);}

function movementDetail(id){const m=findBy("movimentacoes",id);if(!m)return;const items=state.data.movimentacoes.filter(x=>groupKey(x)===groupKey(m));modal(`Movimentação — ${m.colaboradorNome}`,`<div class="detail-grid"><div class="detail-item"><span>Colaborador</span><strong>${esc(m.colaboradorNome)}</strong></div><div class="detail-item"><span>Obra</span><strong>${esc(m.obraNome||"—")}</strong></div><div class="detail-item"><span>Movimento</span><strong>${esc(m.movimento)}</strong></div><div class="detail-item"><span>Assinatura</span><strong>${esc(m.statusAssinatura)}</strong></div><div class="detail-item"><span>Data assinatura</span><strong>${dateTimeBR(m.assinadoEm)}</strong></div><div class="detail-item"><span>Estado</span><strong>${esc(m.estado)}</strong></div></div><div class="section-separator"></div><h4>Itens desta movimentação</h4><div class="timeline">${items.map(x=>`<div class="timeline-item"><strong>${esc(x.itemDescricao)}</strong><span>${esc(x.tipoItem.toUpperCase())} • ${esc(x.caTagSerie||"—")} • Qtd. ${Number(x.quantidade||1)}</span></div>`).join("")}</div><p><strong>Motivo / condição:</strong> ${esc(m.motivoCondicao||"—")}</p>${m.assinaturaBase64?`<div class="section-separator"></div><p class="small muted">Assinado eletronicamente por ${esc(m.assinadoPorNome||m.colaboradorNome)} em ${dateTimeBR(m.assinadoEm)}.</p><img src="${m.assinaturaBase64}" alt="Assinatura" style="max-width:320px;max-height:120px;border:1px solid #ddd;border-radius:8px">`:""}`,{wide:true,footer:`<button class="secondary-button" data-close-modal>Fechar</button>`});}

function openSignature(id){const m=findBy("movimentacoes",id);if(!m||m.statusAssinatura!=="pendente"||m.colaboradorId!==ownCollabId())return;const items=state.data.movimentacoes.filter(x=>groupKey(x)===groupKey(m));modal(`Assinar ${m.assinaturaTipo==="devolucao"?"devolução":"recebimento"}`,`<div class="notice-box"><strong>${items.length} item(ns) nesta movimentação</strong><span>${esc(m.movimento)} • ${esc(m.obraNome||"Sem obra")}</span></div><div class="timeline">${items.map(x=>`<div class="timeline-item"><strong>${esc(x.itemDescricao)}</strong><span>${esc(x.caTagSerie||"")} • Qtd. ${Number(x.quantidade||1)}</span></div>`).join("")}</div><p class="small muted">Declaro que conferi os itens acima e confirmo eletronicamente o ${m.assinaturaTipo==="devolucao"?"registro de devolução":"recebimento em condição adequada de uso, com as orientações necessárias sobre utilização, guarda, conservação e comunicação de defeitos"}.</p><div class="signature-wrap"><canvas id="signature-canvas" class="signature-canvas" width="760" height="220"></canvas></div><div class="signature-tools"><span class="muted small">Assine com o mouse, caneta ou toque.</span><button class="secondary-button" type="button" id="clear-signature">Limpar</button></div><div id="modal-msg"></div>`,{wide:true,footer:`<button class="secondary-button" data-close-modal>Cancelar</button><button class="module-primary-button" id="confirm-signature">Confirmar assinatura</button>`});const canvas=$("#signature-canvas"),ctx=canvas.getContext("2d");ctx.lineWidth=2.2;ctx.lineCap="round";ctx.strokeStyle="#0b3768";let drawing=false,dirty=false;const pos=e=>{const r=canvas.getBoundingClientRect(),p=e.touches?.[0]||e;return{x:(p.clientX-r.left)*(canvas.width/r.width),y:(p.clientY-r.top)*(canvas.height/r.height)}};const start=e=>{drawing=true;dirty=true;const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y);e.preventDefault()};const move=e=>{if(!drawing)return;const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke();e.preventDefault()};const end=e=>{drawing=false;e?.preventDefault?.()};canvas.addEventListener("pointerdown",start);canvas.addEventListener("pointermove",move);canvas.addEventListener("pointerup",end);canvas.addEventListener("pointerleave",end);$("#clear-signature").onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);dirty=false};$("#confirm-signature").onclick=async()=>{if(!dirty){$("#modal-msg").innerHTML=msgBox("Faça sua assinatura antes de confirmar.");return;}try{await finalizeSignature(m,canvas.toDataURL("image/png"));closeModal();showToast("Assinatura registrada para todos os itens.");}catch(err){console.error(err);$("#modal-msg").innerHTML=msgBox(friendlyWriteError(err));}};}
async function finalizeSignature(m,sig){const items=state.data.movimentacoes.filter(x=>groupKey(x)===groupKey(m)&&x.statusAssinatura==="pendente");const batch=writeBatch(db);for(const x of items){const ref=doc(db,"movimentacoes",x.id),base={statusAssinatura:"assinado",assinaturaBase64:sig,assinadoEm:serverTimestamp(),assinadoPor:state.user.uid,assinadoPorNome:state.profile?.nome||x.colaboradorNome};if(x.assinaturaTipo==="devolucao"){batch.update(ref,{...base,estado:"devolvido"});if(x.movimentacaoOrigemId)batch.update(doc(db,"movimentacoes",x.movimentacaoOrigemId),{estado:"devolvido",devolvidoEm:serverTimestamp()});if(x.tipoItem==="kit"){batch.update(doc(db,"kits",x.itemId),{status:"Disponível",responsavelColaboradorId:"",responsavelNome:"",atualizadoEm:serverTimestamp(),atualizadoPor:state.user.uid});for(const c of x.componentesSnapshot||[])batch.update(doc(db,"equipamentos",c.id),{status:"Aguardando inspeção",responsavelColaboradorId:"",responsavelNome:"",atualizadoEm:serverTimestamp(),atualizadoPor:state.user.uid});}else if(x.tipoItem==="equipamento")batch.update(doc(db,"equipamentos",x.itemId),{status:"Aguardando inspeção",responsavelColaboradorId:"",responsavelNome:"",atualizadoEm:serverTimestamp(),atualizadoPor:state.user.uid});}else{let estado="em_posse";if(x.tipoItem==="epi"&&findBy("epis",x.itemId)?.tipoControle==="Consumo")estado="consumido";batch.update(ref,{...base,estado});if(x.tipoItem==="kit"){batch.update(doc(db,"kits",x.itemId),{status:"Em uso",responsavelColaboradorId:x.colaboradorId,responsavelNome:x.colaboradorNome,atualizadoEm:serverTimestamp(),atualizadoPor:state.user.uid});for(const c of x.componentesSnapshot||[])batch.update(doc(db,"equipamentos",c.id),{status:"Em uso",responsavelColaboradorId:x.colaboradorId,responsavelNome:x.colaboradorNome,atualizadoEm:serverTimestamp(),atualizadoPor:state.user.uid});}else if(x.tipoItem==="equipamento")batch.update(doc(db,"equipamentos",x.itemId),{status:"Em uso",responsavelColaboradorId:x.colaboradorId,responsavelNome:x.colaboradorNome,atualizadoEm:serverTimestamp(),atualizadoPor:state.user.uid});}}await batch.commit();await audit("Assinatura","movimentacao",groupKey(m),`${m.colaboradorNome} — ${items.length} item(ns)`);}
async function cancelMovement(id){const m=findBy("movimentacoes",id);if(!m||m.statusAssinatura!=="pendente")return;const items=state.data.movimentacoes.filter(x=>groupKey(x)===groupKey(m)&&x.statusAssinatura==="pendente");if(!confirm(`Cancelar a movimentação com ${items.length} item(ns)?`))return;const batch=writeBatch(db);for(const x of items){batch.update(doc(db,"movimentacoes",x.id),{statusAssinatura:"cancelado",estado:"cancelado",canceladoEm:serverTimestamp(),canceladoPor:state.user.uid});if(x.assinaturaTipo!=="devolucao"){if(x.tipoItem==="epi"){const e=findBy("epis",x.itemId),r=doc(collection(db,"estoque_movimentacoes"));batch.set(r,{epiId:x.itemId,epiNome:e?.nome||x.itemDescricao,tipo:"Estorno de cancelamento",quantidade:Number(x.quantidade||1),obraId:x.obraId||"",obraNome:x.obraNome||"",movimentacaoId:x.id,grupoId:groupKey(m),observacao:`Cancelamento — ${x.colaboradorNome}`,criadoEm:serverTimestamp(),criadoPor:state.user.uid});}else if(x.tipoItem==="kit"){batch.update(doc(db,"kits",x.itemId),{status:"Disponível",responsavelColaboradorId:"",responsavelNome:"",atualizadoEm:serverTimestamp(),atualizadoPor:state.user.uid});for(const c of x.componentesSnapshot||[])batch.update(doc(db,"equipamentos",c.id),{status:"Disponível",responsavelColaboradorId:"",responsavelNome:"",atualizadoEm:serverTimestamp(),atualizadoPor:state.user.uid});}else batch.update(doc(db,"equipamentos",x.itemId),{status:"Disponível",responsavelColaboradorId:"",responsavelNome:"",atualizadoEm:serverTimestamp(),atualizadoPor:state.user.uid});}}await batch.commit();await audit("Cancelamento","movimentacao",groupKey(m),`${items.length} item(ns)`);showToast("Movimentação cancelada.");}
async function createReturn(origin){if(!origin)return;const origins=state.data.movimentacoes.filter(x=>groupKey(x)===groupKey(origin)&&x.statusAssinatura==="assinado"&&x.estado==="em_posse"&&x.tipoItem!=="epi");if(!origins.length)return;const grupoId=(globalThis.crypto?.randomUUID?.()||`ret-${Date.now()}-${Math.random().toString(36).slice(2)}`),batch=writeBatch(db);for(const x of origins){const ref=doc(collection(db,"movimentacoes"));batch.set(ref,{grupoId,grupoQuantidade:origins.length,colaboradorId:x.colaboradorId,colaboradorNome:x.colaboradorNome,obraId:x.obraId||"",obraNome:x.obraNome||"",tipoItem:x.tipoItem,itemId:x.itemId,itemDescricao:x.itemDescricao,caTagSerie:x.caTagSerie||"",quantidade:x.quantidade||1,movimento:"Devolução",motivoCondicao:"Devolução / desmobilização",statusAssinatura:"pendente",estado:"aguardando_assinatura",assinaturaTipo:"devolucao",movimentacaoOrigemId:x.id,componentesSnapshot:x.componentesSnapshot||[],criadoEm:serverTimestamp(),criadoPor:state.user.uid});}await batch.commit();await audit("Devolução criada","movimentacao",grupoId,`${origins.length} item(ns)`);showToast("Devolução enviada para uma única assinatura.");}

function openMobilize(workId){const work=findBy("obras",workId);if(!work)return;const collabs=state.data.colaboradores.filter(c=>c.ativo!==false).sort((a,b)=>byName(a,b,"nomeCompleto"));const epis=state.data.epis.filter(e=>e.ativo!==false).sort((a,b)=>byName(a,b,"nome"));const kits=state.data.kits.filter(k=>k.status==="Disponível").sort((a,b)=>byName(a,b,"codigo"));const cords=state.data.equipamentos.filter(e=>e.tipo==="Corda"&&e.status==="Disponível").sort((a,b)=>byName(a,b,"tag"));modal(`Mobilizar — ${work.nome}`,`<form id="mobilize-form"><div class="form-grid">${selectField("Colaborador","colaboradorId",[["","Selecione"],...collabs.map(c=>[c.id,c.nomeCompleto])],"",{required:true})}</div><div class="section-separator"></div><div class="three-column"><div><label class="strong small">EPIs para esta obra</label><div class="checkbox-list">${epis.map(e=>`<label class="checkbox-item"><input type="checkbox" name="epis" value="${e.id}"><span>${esc(e.nome)} <span class="muted">(saldo ${stockFor(e.id)})</span></span></label>`).join("")||"<div class='empty-state'>Sem EPIs</div>"}</div></div><div><label class="strong small">KITs</label><div class="checkbox-list">${kits.map(k=>`<label class="checkbox-item"><input type="checkbox" name="kits" value="${k.id}"><span><strong>${esc(k.codigo)}</strong> — ${esc(k.categoria||k.descricao||"KIT")}</span></label>`).join("")||"<div class='empty-state'>Sem KITs disponíveis</div>"}</div></div><div><label class="strong small">Cordas avulsas</label><div class="checkbox-list">${cords.map(e=>`<label class="checkbox-item"><input type="checkbox" name="cordas" value="${e.id}"><span><strong>${esc(e.tag)}</strong> — ${esc(e.equipamento)} ${e.comprimentoAtual?`(${e.comprimentoAtual} m)`:""}</span></label>`).join("")||"<div class='empty-state'>Sem cordas disponíveis</div>"}</div></div></div><div class="form-help">Toda a mobilização selecionada será enviada ao colaborador em uma única assinatura.</div><div id="modal-msg"></div></form>`,{wide:true,footer:`<button class="secondary-button" data-close-modal>Cancelar</button><button class="module-primary-button" type="submit" form="mobilize-form">Gerar mobilização</button>`});$("#mobilize-form").onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),cid=fd.get("colaboradorId"),items=[];for(const id of fd.getAll("epis"))items.push({tipoItem:"epi",itemId:id,quantidade:1});for(const id of fd.getAll("kits"))items.push({tipoItem:"kit",itemId:id,quantidade:1});for(const id of fd.getAll("cordas"))items.push({tipoItem:"equipamento",itemId:id,quantidade:1});if(!cid){$("#modal-msg").innerHTML=msgBox("Selecione o colaborador.");return;}if(!items.length){$("#modal-msg").innerHTML=msgBox("Selecione ao menos um EPI, KIT ou corda.");return;}try{const mobRef=await addDoc(collection(db,"mobilizacoes"),{obraId:work.id,obraNome:work.nome,colaboradorId:cid,colaboradorNome:findBy("colaboradores",cid)?.nomeCompleto||"",status:"Aguardando assinatura",criadoEm:serverTimestamp(),criadoPor:state.user.uid});await createMovementGroup({colaboradorId:cid,obraId:work.id,movimento:"Mobilização",motivoCondicao:"Mobilização para obra",items},{mobilizacaoId:mobRef.id});if(work.status==="Planejada")await updateDoc(doc(db,"obras",work.id),{status:"Em andamento",atualizadoEm:serverTimestamp(),atualizadoPor:state.user.uid});await audit("Mobilização","obra",work.id,findBy("colaboradores",cid)?.nomeCompleto||"");closeModal();showToast("Mobilização criada para uma única assinatura.");}catch(err){console.error(err);$("#modal-msg").innerHTML=msgBox(friendlyWriteError(err));}};}
function openDemobilize(workId){const work=findBy("obras",workId);const active=state.data.movimentacoes.filter(m=>m.obraId===workId&&m.statusAssinatura==="assinado"&&m.estado==="em_posse"&&["kit","equipamento"].includes(m.tipoItem));modal(`Desmobilizar — ${work?.nome||"Obra"}`,`<p class="muted small">Serão geradas devoluções para KITs e equipamentos/cordas ainda em posse dos colaboradores. As devoluções só serão concluídas após assinatura.</p><div class="checkbox-list">${active.map(m=>`<label class="checkbox-item"><input type="checkbox" name="returns" value="${m.id}" checked><span>${esc(m.colaboradorNome)} — <strong>${esc(m.itemDescricao)}</strong></span></label>`).join("")||`<div class="empty-state">Não há KITs ou equipamentos aguardando devolução.</div>`}</div><div id="modal-msg"></div>`,{wide:true,footer:`<button class="secondary-button" data-close-modal>Fechar</button>${active.length?`<button class="module-primary-button" id="confirm-demob">Gerar devoluções</button>`:""}`});if(active.length)$("#confirm-demob").onclick=async()=>{const ids=[...ui.modalHost.querySelectorAll('input[name="returns"]:checked')].map(x=>x.value);if(!ids.length)return;try{for(const id of ids)await createReturn(findBy("movimentacoes",id));await audit("Desmobilização iniciada","obra",workId,`${ids.length} devolução(ões)`);closeModal();showToast("Devoluções geradas para assinatura.");}catch(err){$("#modal-msg").innerHTML=msgBox("Erro na desmobilização: "+(err.code||err.message||""));}};}

function renderReports(){const collabs=state.data.colaboradores.filter(c=>c.ativo!==false).sort((a,b)=>byName(a,b,"nomeCompleto"));const isCollab=norm(state.profile?.role)==="colaborador",selected=isCollab?ownCollabId():"";const works=isCollab?[...new Map(state.data.movimentacoes.filter(m=>m.obraId).map(m=>[m.obraId,{id:m.obraId,nome:m.obraNome}])).values()]:state.data.obras.sort((a,b)=>byName(a,b,"nome"));const equipments=isCollab?[]:state.data.equipamentos.sort((a,b)=>byName(a,b,"tag"));ui.root.innerHTML=moduleHeader("DOCUMENTOS","Relatórios e fichas","Gere documentos corporativos em PDF com cabeçalho e rodapé da Safety Equipamentos.")+`<div class="two-column"><article class="section-card"><span class="eyebrow">SE-FRM-SST-004</span><h3>Ficha de EPI do colaborador</h3><p class="muted small">Histórico completo ou recorte dos itens destinados a uma obra.</p><div class="form-grid">${selectField("Colaborador","report-collab",collabs.map(c=>[c.id,c.nomeCompleto]),selected,{disabled:isCollab})}${selectField("Obra (opcional)","report-work",[["","Ficha completa"],...works.map(o=>[o.id,o.nome])])}</div><div class="action-row"><button class="module-primary-button" data-action="pdf-epi">Gerar PDF</button></div></article>${isCollab?"":`<article class="section-card"><span class="eyebrow">SE-FRM-AC-002</span><h3>Rastreabilidade de equipamento</h3><p class="muted small">Cadastro, aquisição, uso, inspeção, manutenção, quarentena e descarte.</p><div class="form-grid">${selectField("Equipamento / TAG","report-equipment",equipments.map(e=>[e.id,`${e.tag} — ${e.equipamento}`]))}</div><div class="action-row"><button class="module-primary-button" data-action="pdf-trace">Gerar PDF</button></div></article>`}</div>${isCollab?"":`<div class="section-separator"></div><article class="section-card"><span class="eyebrow">RESUMO OPERACIONAL</span><h3>Ficha da obra</h3><p class="muted small">Gera uma relação consolidada dos colaboradores e itens em uso na obra selecionada.</p><div class="form-grid">${selectField("Obra","report-work-summary",works.map(o=>[o.id,o.nome]))}</div><div class="action-row"><button class="module-primary-button" data-action="pdf-work">Gerar PDF da obra</button></div></article>`}`;}
function pdfLib(){if(!window.jspdf?.jsPDF)throw new Error("Biblioteca de PDF não carregou. Atualize a página e tente novamente.");return window.jspdf.jsPDF;}
async function logoData(){try{const img=new Image();img.crossOrigin="anonymous";img.src="./assets/logo-safety.png";await new Promise((res,rej)=>{img.onload=res;img.onerror=rej});const c=document.createElement("canvas");c.width=img.naturalWidth;c.height=img.naturalHeight;c.getContext("2d").drawImage(img,0,0);return c.toDataURL("image/png");}catch{return null;}}
function pdfHeader(doc,title,code,page){doc.setTextColor(7,59,115);doc.setFont("helvetica","bold");doc.setFontSize(13);doc.text("SAFETY EQUIPAMENTOS",200,14,{align:"right"});doc.setFont("helvetica","normal");doc.setFontSize(7);doc.setTextColor(90);doc.text("atendimento@safetyequipamentos.com | (21) 2756-5524 | WhatsApp (21) 99532-0709",200,19,{align:"right"});doc.text("www.safetyequipamentos.com | CNPJ 22.015.773/0001-84",200,23,{align:"right"});doc.setDrawColor(7,59,115);doc.setLineWidth(1.8);doc.line(12,29,160,29);doc.setDrawColor(212,160,23);doc.line(160,29,200,29);doc.setFontSize(7);doc.setTextColor(110);doc.text("Rua José de Queiroz, 196 - Bento Ribeiro - Rio de Janeiro/RJ",12,290);doc.text(`${code} | REV. 00`,105,290,{align:"center"});doc.text(`PÁG. ${page}`,200,290,{align:"right"});doc.setFontSize(15);doc.setTextColor(7,59,115);doc.setFont("helvetica","bold");doc.text(title,12,40);}
function addPdfFooters(doc,title,code){const pages=doc.getNumberOfPages();for(let i=1;i<=pages;i++){doc.setPage(i);pdfHeader(doc,title,code,i);}}
async function generateEpiPdf(collabId,workId=""){const c=findBy("colaboradores",collabId);if(!c)throw new Error("Selecione o colaborador.");const work=findBy("obras",workId);let ms=state.data.movimentacoes.filter(m=>m.colaboradorId===collabId&&m.statusAssinatura!=="cancelado");if(workId){ms=ms.filter(m=>m.obraId===workId&&m.statusAssinatura==="assinado"&&(m.tipoItem==="epi"||m.estado==="em_posse"));}ms.sort((a,b)=>(a.criadoEm?.seconds||0)-(b.criadoEm?.seconds||0));const J=pdfLib(),doc=new J({unit:"mm",format:"a4"});doc.setFont("helvetica","normal");doc.setTextColor(20);doc.setFontSize(8);doc.text(workId?`RECORTE OPERACIONAL POR OBRA: ${work?.nome||""}`:"FORMULÁRIO CORPORATIVO DE SST",12,48);doc.setFontSize(10);doc.setFont("helvetica","bold");doc.text("1. IDENTIFICAÇÃO DO EMPREGADO",12,56);doc.autoTable({startY:60,theme:"grid",styles:{fontSize:8,cellPadding:2},head:[['Nome completo','Matrícula/cadastro','Cargo/função']],body:[[c.nomeCompleto,c.matricula||'',c.cargoFuncao||''],['Setor/contrato',c.setorContrato||'',`Admissão: ${dateBR(c.dataAdmissao)}`]],margin:{left:12,right:10}});let y=doc.lastAutoTable.finalY+7;doc.setFont("helvetica","bold");doc.setFontSize(10);doc.text("2. CIÊNCIA E RESPONSABILIDADES",12,y);doc.setFont("helvetica","normal");doc.setFontSize(7.5);const resp="Declaro que recebi gratuitamente os itens registrados nesta ficha, em condição adequada de uso, acompanhados das orientações necessárias sobre ajuste, utilização, limitações, higienização, guarda, conservação e comunicação de defeitos. Devo utilizar o EPI para a finalidade prevista, inspecionar antes do uso, comunicar danos ou alterações e devolver os itens sujeitos a controle quando solicitado.";doc.text(doc.splitTextToSize(resp,186),12,y+5);y+=25;doc.setFont("helvetica","bold");doc.setFontSize(10);doc.text("3. MOVIMENTAÇÃO DE EPI E UNIFORMES",12,y);doc.autoTable({startY:y+4,theme:"grid",styles:{fontSize:6.7,cellPadding:1.5},head:[['DATA','QTD.','EPI / UNIFORME / EQUIPAMENTO','CA / TAG / SÉRIE','MOVIMENTO','MOTIVO / CONDIÇÃO','ASSINATURA']],body:ms.map(m=>[dateBR(m.criadoEm),String(m.quantidade||1),m.itemDescricao||'',m.caTagSerie||'',m.movimento||'',m.motivoCondicao||'',m.statusAssinatura==="assinado"?`Eletrônica ${dateTimeBR(m.assinadoEm)}`:'Pendente']),margin:{left:12,right:10}});y=doc.lastAutoTable.finalY+7;if(y>250){doc.addPage();y=47;}doc.setFont("helvetica","bold");doc.setFontSize(10);doc.text("4. DECLARAÇÃO FINAL",12,y);doc.setFont("helvetica","normal");doc.setFontSize(7.5);doc.text(doc.splitTextToSize("Confirmo que as informações registradas nesta ficha correspondem às movimentações realizadas. Estou ciente de que devo cumprir as orientações de SST, comunicar qualquer condição insegura e devolver os itens sujeitos a controle quando solicitado.",186),12,y+5);const signed=ms.filter(m=>m.assinaturaBase64);if(signed.length){y+=22;doc.setFont("helvetica","bold");doc.text("REGISTROS DE ASSINATURA ELETRÔNICA",12,y);for(const m of signed.slice(-4)){if(y>255){doc.addPage();y=48;}y+=5;doc.setFont("helvetica","normal");doc.setFontSize(7);doc.text(`${m.itemDescricao} — ${dateTimeBR(m.assinadoEm)} — ${m.assinadoPorNome||c.nomeCompleto}`,12,y);try{doc.addImage(m.assinaturaBase64,"PNG",14,y+2,48,14);y+=18;}catch{y+=4;}}}addPdfFooters(doc,workId?"FICHA DE EPI — OBRA":"FICHA DE ENTREGA, RECEBIMENTO E CONTROLE DE EPI E UNIFORMES","SE-FRM-SST-004");doc.save(`Ficha_EPI_${c.nomeCompleto.replace(/\s+/g,"_")}${workId?`_${work?.nome?.replace(/\s+/g,"_")}`:""}.pdf`);await audit("PDF gerado","relatorio",collabId,workId?`Ficha de obra ${work?.nome}`:"Ficha completa");}
async function generateTracePdf(id){const e=findBy("equipamentos",id);if(!e)throw new Error("Selecione o equipamento.");const inspections=state.data.inspecoes.filter(i=>i.equipamentoId===id);const direct=state.data.movimentacoes.filter(m=>m.tipoItem==="equipamento"&&m.itemId===id);const kit=state.data.movimentacoes.filter(m=>m.tipoItem==="kit"&&(m.componentesSnapshot||[]).some(c=>c.id===id));const history=[...inspections.map(i=>({data:i.data,evento:"Inspeção",local:"",servico:i.tipoInspecao,resultado:i.resultado,acao:i.acaoManutencao,proxima:i.proximaInspecao,responsavel:i.responsavel,evidencia:i.evidencia||i.observacoes})),...direct.map(m=>({data:m.criadoEm,evento:m.movimento,local:m.obraNome,servico:`Responsável: ${m.colaboradorNome}`,resultado:m.statusAssinatura,acao:m.estado,proxima:"",responsavel:m.assinadoPorNome||"",evidencia:m.motivoCondicao})),...kit.map(m=>({data:m.criadoEm,evento:`KIT ${m.itemDescricao}`,local:m.obraNome,servico:`Responsável: ${m.colaboradorNome}`,resultado:m.statusAssinatura,acao:m.estado,proxima:"",responsavel:m.assinadoPorNome||"",evidencia:"Componente de KIT"}))].sort((a,b)=>{const da=a.data?.toDate?a.data.toDate():new Date(a.data||0),dbb=b.data?.toDate?b.data.toDate():new Date(b.data||0);return da-dbb;});const J=pdfLib(),doc=new J({unit:"mm",format:"a4"});doc.setFontSize(8);doc.setTextColor(30);doc.autoTable({startY:48,theme:"grid",styles:{fontSize:7,cellPadding:2},body:[['Equipamento',e.equipamento,'TAG',e.tag],['Fabricante',e.fabricante||'','Modelo',e.modelo||''],['Nº de série',e.numeroSerie||'','Lote / fabricação',e.loteFabricacao||''],['Data de compra',dateBR(e.dataCompra),'Nota fiscal',e.notaFiscal||''],['Vida útil / validade',e.vidaUtilValidade||'','Status atual',e.status||''],['Norma / certificação',e.normaCertificacao||'','Tipo',e.tipo||'Equipamento']],margin:{left:12,right:10}});let y=doc.lastAutoTable.finalY+8;doc.setFont("helvetica","bold");doc.setFontSize(10);doc.text("HISTÓRICO DO EQUIPAMENTO",12,y);doc.autoTable({startY:y+4,theme:"grid",styles:{fontSize:5.7,cellPadding:1.3},head:[['DATA','EVENTO','PROJETO / LOCAL','SERVIÇO / INSPEÇÃO','RESULTADO','AÇÃO / MANUTENÇÃO','PRÓXIMA INSPEÇÃO','RESPONSÁVEL','EVIDÊNCIA / OBS.']],body:history.map(h=>[dateBR(h.data),h.evento||'',h.local||'',h.servico||'',h.resultado||'',h.acao||'',dateBR(h.proxima),h.responsavel||'',h.evidencia||'']),margin:{left:8,right:8}});const yy=Math.min(doc.lastAutoTable.finalY+6,275);if(yy<275){doc.setFontSize(6.4);doc.setTextColor(80);doc.text(doc.splitTextToSize("CRITÉRIO: equipamento ou corda com defeito, desgaste, degradação, deformação, contaminação, alteração, impacto, rastreabilidade insuficiente ou histórico desconhecido deve ser retirado de uso, identificado e tratado conforme fabricante, NR-35 e procedimento interno.",190),10,yy);}addPdfFooters(doc,"RASTREABILIDADE DE EQUIPAMENTO DE ACESSO POR CORDAS","SE-FRM-AC-002");doc.save(`Rastreabilidade_${e.tag}.pdf`);await audit("PDF gerado","equipamento",e.id,`Rastreabilidade ${e.tag}`);}
async function generateWorkPdf(workId){const w=findBy("obras",workId);if(!w)throw new Error("Selecione a obra.");const active=state.data.movimentacoes.filter(m=>m.obraId===workId&&m.statusAssinatura==="assinado"&&(m.tipoItem==="epi"||m.estado==="em_posse"));const J=pdfLib(),doc=new J({unit:"mm",format:"a4"});doc.setFontSize(9);doc.text(`Cliente: ${w.cliente||"—"}`,12,49);doc.text(`Status: ${w.status||"—"}`,12,54);doc.autoTable({startY:60,theme:"grid",styles:{fontSize:7,cellPadding:2},head:[['COLABORADOR','ITEM','TIPO','CA / TAG / SÉRIE','QTD.','ASSINADO EM']],body:active.map(m=>[m.colaboradorNome,m.itemDescricao,m.tipoItem.toUpperCase(),m.caTagSerie||'',String(m.quantidade||1),dateTimeBR(m.assinadoEm)]),margin:{left:12,right:10}});addPdfFooters(doc,`FICHA OPERACIONAL DE EPI E EQUIPAMENTOS — ${w.nome}`,"SE-FRM-SST-004");doc.save(`Ficha_Obra_${w.nome.replace(/\s+/g,"_")}.pdf`);await audit("PDF gerado","obra",w.id,"Ficha operacional da obra");}

function renderUsers(){if(!isAdmin()){navigate("dashboard");return;}const rows=[...state.data.usuarios].sort((a,b)=>byName(a,b,"nome"));ui.root.innerHTML=moduleHeader("CONTROLE DE ACESSO","Usuários","As contas de Authentication continuam sendo criadas no Firebase Console. Aqui o Administrador cria/vincula o perfil do sistema.",`<button class="module-primary-button" data-action="new-user-profile">+ Novo perfil de usuário</button>`)+`<div class="warning-strip">Para um novo usuário: primeiro crie a conta em Firebase Authentication e copie o UID. Depois cadastre o perfil aqui. O perfil Administrador permanece reservado à conta administrativa atual.</div><div class="section-separator"></div><div class="module-card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Colaborador vinculado</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(u=>`<tr><td><strong>${esc(u.nome||"—")}</strong></td><td>${esc(u.email||"—")}</td><td>${esc(roleLabel(u.role))}</td><td>${esc(findBy("colaboradores",u.colaboradorId)?.nomeCompleto||"Não vinculado")}</td><td>${badge(u.ativo===false?"Inativo":"Ativo",u.ativo===false?"inactive":"active")}</td><td><button class="table-action-button" data-action="edit-user-profile" data-id="${u.id}">Editar</button></td></tr>`).join("")||`<tr><td colspan="6" class="empty-state">Nenhum perfil encontrado.</td></tr>`}</tbody></table></div></div>`;}
function openUserProfile(id=""){const u=id?findBy("usuarios",id):{},creating=!id;if(!isAdmin())return;const collabs=state.data.colaboradores.filter(c=>c.ativo!==false||c.id===u?.colaboradorId).sort((a,b)=>byName(a,b,"nomeCompleto"));const isProtectedAdmin=!creating&&u?.role==="administrador";const roleOptions=isProtectedAdmin?["administrador"]:["master","gestor","colaborador"];modal(creating?"Novo perfil de usuário":"Editar perfil de usuário",`<form id="user-form"><div class="form-grid">${field("UID do Firebase Authentication","uid",u?.id||"",{required:true,disabled:!creating})}${field("Nome da conta","nome",u?.nome||"",{required:true})}${field("E-mail","email",u?.email||"",{type:"email",required:true,disabled:!creating})}${selectField("Perfil de acesso","role",roleOptions.map(r=>[r,roleLabel(r)]),u?.role||"colaborador",{disabled:isProtectedAdmin})}${selectField("Colaborador correspondente","colaboradorId",[["","Não vinculado"],...collabs.map(c=>[c.id,c.nomeCompleto])],u?.colaboradorId||"")}${selectField("Status","ativo",[["true","Ativo"],["false","Inativo"]],u?.ativo===false?"false":"true",{disabled:isProtectedAdmin})}</div>${isProtectedAdmin?`<div class="warning-strip">Por segurança, o perfil Administrador não pode ser rebaixado nem desativado por esta tela.</div>`:""}<div id="modal-msg"></div></form>`,{footer:`<button class="secondary-button" data-close-modal>Cancelar</button><button class="module-primary-button" type="submit" form="user-form">Salvar perfil</button>`});$("#user-form").onsubmit=async e=>{e.preventDefault();const f=formDataObj(e.target),uid=creating?(f.uid||"").trim():id;if(!uid)return;const finalRole=isProtectedAdmin?"administrador":norm(f.role);const payload={nome:(f.nome||u?.nome||"").trim(),role:finalRole,colaboradorId:f.colaboradorId||"",ativo:isProtectedAdmin?true:f.ativo==="true",atualizadoEm:serverTimestamp(),atualizadoPor:state.user.uid};if(creating)payload.email=(f.email||"").trim();try{if(creating)await setDoc(doc(db,"usuarios",uid),{...payload,criadoEm:serverTimestamp(),criadoPor:state.user.uid});else await updateDoc(doc(db,"usuarios",uid),payload);if(uid===state.user.uid)state.profile={...state.profile,...payload};await audit(creating?"Perfil criado":"Perfil atualizado","usuario",uid,payload.email||u?.email||"");closeModal();showToast("Perfil de usuário salvo.");}catch(err){console.error(err);$("#modal-msg").innerHTML=msgBox(friendlyWriteError(err));}};}


function renderAudit(){if(!isMgmt()){navigate("dashboard");return;}const all=[...state.data.auditoria].sort((a,b)=>(b.criadoEm?.seconds||0)-(a.criadoEm?.seconds||0));const users=[...new Set(all.map(x=>x.usuarioNome).filter(Boolean))].sort();const entities=[...new Set(all.map(x=>x.entidade).filter(Boolean))].sort();ui.root.innerHTML=moduleHeader("HISTÓRICO DO SISTEMA","Auditoria","Registro das principais ações executadas no Safety EPI.")+`<div class="module-toolbar"><input class="search-input" id="audit-search" placeholder="Pesquisar evento, usuário ou detalhes"><input class="filter-select" type="date" id="audit-date"><select id="audit-user" class="filter-select"><option value="">Todos os usuários</option>${users.map(x=>`<option>${esc(x)}</option>`).join("")}</select><select id="audit-entity" class="filter-select"><option value="">Todas as entidades</option>${entities.map(x=>`<option>${esc(x)}</option>`).join("")}</select></div><div class="module-card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Usuário</th><th>Evento</th><th>Entidade</th><th>Detalhes</th></tr></thead><tbody id="audit-body"></tbody></table></div></div>`;const paint=()=>{const q=$("#audit-search").value.toLowerCase(),date=$("#audit-date").value,user=$("#audit-user").value,entity=$("#audit-entity").value;const rows=all.filter(a=>{const txt=[a.usuarioNome,a.evento,a.entidade,a.detalhes].join(" ").toLowerCase();const d=a.criadoEm?.toDate?a.criadoEm.toDate():null,iso=d?d.toISOString().slice(0,10):"";return(!q||txt.includes(q))&&(!date||iso===date)&&(!user||a.usuarioNome===user)&&(!entity||a.entidade===entity)}).slice(0,500);$("#audit-body").innerHTML=rows.map(a=>`<tr><td>${dateTimeBR(a.criadoEm)}</td><td>${esc(a.usuarioNome||"—")}</td><td><strong>${esc(a.evento||"—")}</strong></td><td>${esc(a.entidade||"—")}</td><td>${esc(a.detalhes||"—")}</td></tr>`).join("")||`<tr><td colspan="5" class="empty-state">Sem registros para os filtros selecionados.</td></tr>`;};paint();["audit-search","audit-date","audit-user","audit-entity"].forEach(id=>$("#"+id).addEventListener(id==="audit-search"?"input":"change",paint));}

function handleAction(action,id){const map={
  "new-collab":()=>openCollaborator(),"edit-collab":()=>openCollaborator(id),"collab-history":()=>showCollaboratorHistory(id),
  "new-work":()=>openWork(),"edit-work":()=>openWork(id),"mobilize":()=>openMobilize(id),"demobilize":()=>openDemobilize(id),
  "new-epi":()=>openEpi(),"edit-epi":()=>openEpi(id),"new-equipment":()=>openEquipment(),"edit-equipment":()=>openEquipment(id),
  "equipment-detail":()=>equipmentHistory(id),"equipment-qr":()=>showQR(id),"new-kit":()=>openKit(),"edit-kit":()=>openKit(id),"kit-detail":()=>kitDetail(id),
  "stock-entry":()=>openStockEntry(),"new-inspection":()=>openInspection(id||""),"inspection-detail":()=>inspectionDetail(id),
  "new-movement":()=>openMovement(),"movement-detail":()=>movementDetail(id),"sign-movement":()=>openSignature(id),"cancel-movement":()=>cancelMovement(id),
  "return-movement":()=>createReturn(findBy("movimentacoes",id)),"new-user-profile":()=>openUserProfile(),"edit-user-profile":()=>openUserProfile(id),
  "pdf-epi":()=>generateEpiPdf($("#report-collab")?.value,$("#report-work")?.value||"").catch(e=>showToast(e.message)),
  "pdf-trace":()=>generateTracePdf($("#report-equipment")?.value).catch(e=>showToast(e.message)),
  "pdf-work":()=>generateWorkPdf($("#report-work-summary")?.value).catch(e=>showToast(e.message))
};if(map[action])map[action]();}

document.addEventListener("click",e=>{const close=e.target.closest("[data-close-modal]");if(close){if(e.target.matches(".modal-backdrop")||e.target.closest("button"))closeModal();return;}const nav=e.target.closest("[data-nav]");if(nav){navigate(nav.dataset.nav);return;}const a=e.target.closest("[data-action]");if(a&&!a.disabled){handleAction(a.dataset.action,a.dataset.id||"");}});
ui.menuToggle.onclick=()=>{ui.sidebar.classList.toggle("open");ui.backdrop.classList.toggle("hidden")};ui.backdrop.onclick=()=>{ui.sidebar.classList.remove("open");ui.backdrop.classList.add("hidden")};ui.togglePassword.onclick=()=>{ui.password.type=ui.password.type==="password"?"text":"password"};
ui.loginForm.onsubmit=async e=>{e.preventDefault();ui.loginMessage.className="message hidden";ui.loginButton.disabled=true;try{await signInWithEmailAndPassword(auth,ui.email.value.trim(),ui.password.value);}catch(err){ui.loginMessage.textContent=authMessage(err);ui.loginMessage.className="message error";ui.loginButton.disabled=false;}};
ui.logout.onclick=async()=>{stopData();await signOut(auth)};
window.addEventListener("keydown",e=>{if(e.key==="Escape")closeModal()});

async function handleDeepLink(){const p=new URLSearchParams(location.search),eq=p.get("equipamento");if(eq&&findBy("equipamentos",eq)){state.pendingDeepLink=null;navigate("equipamentos");setTimeout(()=>equipmentHistory(eq),100);}else if(eq)state.pendingDeepLink=eq;}

try{await setPersistence(auth,browserLocalPersistence);}catch(e){console.warn(e)}
onAuthStateChanged(auth,async user=>{if(!user){state.user=null;state.profile=null;stopData();ui.loginButton.disabled=false;showLogin();return;}ui.loading.classList.remove("hidden");ui.loginView.classList.add("hidden");ui.appView.classList.add("hidden");try{state.user=user;state.profile=await loadProfile(user);startData();showApp();setTimeout(handleDeepLink,900);}catch(err){console.error(err);await signOut(auth);ui.loginMessage.textContent=authMessage(err);ui.loginMessage.className="message error";showLogin();}});
